mapper.select:

select * 
from tb_material
where mat_code = #{code}
  and mat_jil = #{jil}
  and mat_hcd = #{hcd}

mapper.update:

INSERT INTO tb_material(
        mat_code
        ,mat_jil
        ,mat_hcd
        ,mat_unit
        ,mat_qty
        ,mat_stock
        ,mat_indte
        ,mat_updte
    ) VALUES(
        #{matCode}
        ,#{matJil}
        ,#{matHcd}
        ,#{matUnit}
        ,#{matQty}
        ,#{matStock}
        ,NOW()
        ,NOW()
    ) ON DUPLICATE KEY UPDATE 
        mat_unit = #{matUnit}
        ,mat_qty = #{matQty}
        ,mat_stock = #{matStock}
        ,mat_updte = NOW()

mapper.delete:

delete from tb_material
where mat_code = #{matCode}
  and mat_jil = #{matJil}
  and mat_hcd = #{matHcd}
